import json
import os
import sys
from decimal import Decimal

FACT_MAPPING = {
    ("usa.period_3y", "performance start"): ("usaspending_awards", ["period_of_performance", "start_date"], "date"),
    ("usa.period_3y", "performance end"): ("usaspending_awards", ["period_of_performance", "end_date"], "date"),
    ("usa.obligated_95", "amount obligated"): ("usaspending_awards", ["total_obligation"], "amount"),
    ("usa.obligated_95", "potential value"): ("usaspending_awards", ["base_and_all_options"], "amount"),
}


def format_amount(value):
    return str(Decimal(str(value)).quantize(Decimal("0.01")))


def format_date(value):
    s = str(value)
    if " " in s:
        s = s.split(" ")[0]
    return s[:10]


def get_nested(record, path):
    val = record
    for key in path:
        if isinstance(val, dict):
            val = val.get(key)
        else:
            return None
    return val


def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load all referenced documents
    docs = {}
    doc_names = {v[0] for v in FACT_MAPPING.values()}
    for doc_name in doc_names:
        path = os.path.join(packet_dir, doc_name + ".json")
        if os.path.exists(path):
            with open(path) as f:
                docs[doc_name] = json.load(f)

    # Build index for usaspending_awards by generated_unique_award_id
    awards_index = {}
    for record in docs.get("usaspending_awards", []):
        gid = record.get("generated_unique_award_id")
        if gid:
            awards_index.setdefault(gid, []).append(record)

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts_for_rule = manifest["facts"].get(rule_id, [])

        records = awards_index.get(entity, [])

        fact_results = {}
        for fact_name in facts_for_rule:
            key = (rule_id, fact_name)
            if key not in FACT_MAPPING:
                fact_results[fact_name] = "ABSENT"
                continue

            doc_name, field_path, val_type = FACT_MAPPING[key]

            values = []
            for record in records:
                val = get_nested(record, field_path)
                if val is not None:
                    if val_type == "date":
                        formatted = format_date(val)
                    else:
                        formatted = format_amount(val)
                    if formatted is not None:
                        values.append(formatted)

            if not values:
                fact_results[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                fact_results[fact_name] = [values[0], doc_name]
            else:
                fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

