import json
import os
import sys
from decimal import Decimal, InvalidOperation
from collections import defaultdict

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts = manifest["facts"]

    manifest_filename = os.path.basename(manifest_path)

    # Load all JSON files in the directory
    documents = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith(".json") and filename != manifest_filename:
            doc_name = filename[:-5]
            filepath = os.path.join(packet_dir, filename)
            with open(filepath) as f:
                documents[doc_name] = json.load(f)

    # Build a map from generated_unique_award_id to list of (document, award)
    awards_by_id = defaultdict(list)
    for doc_name, content in documents.items():
        if isinstance(content, list):
            for item in content:
                if isinstance(item, dict):
                    guid = item.get("generated_unique_award_id")
                    if guid is not None:
                        awards_by_id[str(guid)].append((doc_name, item))
        elif isinstance(content, dict):
            guid = content.get("generated_unique_award_id")
            if guid is not None:
                awards_by_id[str(guid)].append((doc_name, content))

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])

        matching = awards_by_id.get(entity, [])

        fact_results = {}
        for fact_name in fact_names:
            field = get_field(rule_id, fact_name)
            if field is None:
                fact_results[fact_name] = "ABSENT"
                continue

            values = []
            for doc_name, award in matching:
                val = get_nested(award, field)
                if val is not None:
                    if rule_id == "usa.obligated_95":
                        val = format_amount(val)
                    elif rule_id == "usa.period_3y":
                        val = format_date(val)
                    values.append((val, doc_name))

            if len(values) == 0:
                fact_results[fact_name] = "ABSENT"
            else:
                unique_values = set(v[0] for v in values)
                if len(unique_values) == 1:
                    fact_results[fact_name] = [values[0][0], values[0][1]]
                else:
                    fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result, indent=2))

def get_field(rule_id, fact_name):
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            return "period_of_performance.start_date"
        elif fact_name == "performance end":
            return "period_of_performance.end_date"
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            return "total_obligation"
        elif fact_name == "potential value":
            return "base_and_all_options"
    return None

def get_nested(obj, path):
    parts = path.split(".")
    current = obj
    for part in parts:
        if isinstance(current, dict):
            current = current.get(part)
        else:
            return None
        if current is None:
            return None
    return current

def format_amount(val):
    try:
        return str(Decimal(str(val)))
    except (InvalidOperation, ValueError):
        return str(val)

def format_date(val):
    if isinstance(val, str):
        if ' ' in val:
            return val.split(' ')[0]
        return val
    return str(val)

if __name__ == "__main__":
    main()

